(2, 42, '562', '2001-06-04', '738', 'Hillary Fowler', NULL, 25.08, 'Justin Klein', 'Eos ut in nisi vel o', '737', '2014-03-19', 25.08, NULL, '\r\n<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <!-- Bootstrap 5 CSS -->\r\n<link href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css\" rel=\"stylesheet\">\r\n    <title>University of Madras Voucher</title>\r\n    <style>\r\n        * {\r\n            margin: 0;\r\n            padding: 0;\r\n            box-sizing: border-box;\r\n        }\r\n\r\n        body {\r\n            font-family: \'Times New Roman\', serif;\r\n            font-size: 12px;\r\n            line-height: 1.4;\r\n            background: #f5f5f0;\r\n            color: black;\r\n            padding: 15px;\r\n        }\r\n\r\n        .voucher-container {\r\n            width: 210mm;\r\n            min-height: 297mm;\r\n            margin: 0 auto;\r\n            background: #f8f8f5;\r\n            border: 2px solid black;\r\n            position: relative;\r\n        }\r\n\r\n        /* Header Section */\r\n        .header {\r\n            display: flex;\r\n            align-items: center;\r\n            padding: 15px 20px;\r\n            border-bottom: 1px solid black;\r\n        }\r\n\r\n        .logo-section {\r\n            width: 70px;\r\n            height: 70px;\r\n            border: 2px solid black;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            margin-right: 20px;\r\n            background: white;\r\n            flex-shrink: 0;\r\n        }\r\n\r\n        .logo-content {\r\n            text-align: center;\r\n            font-size: 8px;\r\n            font-weight: bold;\r\n        }\r\n\r\n        .university-header {\r\n            flex-grow: 1;\r\n            text-align: center;\r\n        }\r\n\r\n        .university-header