n        .dots-line {\r\n            flex-grow: 1;\r\n            border-bottom: 1px dotted black;\r\n            height: 16px;\r\n        }\r\n\r\n        .debit-text {\r\n            font-size: 11px;\r\n            margin: 8px 0;\r\n        }\r\n\r\n        .signature-area {\r\n            margin-top: 30px;\r\n            text-align: right;\r\n        }\r\n\r\n        .signature-line {\r\n            width: 150px;\r\n            border-top: 1px solid black;\r\n            margin: 25px 0 5px auto;\r\n        }\r\n\r\n        .signature-text {\r\n            font-size: 11px;\r\n            font-weight: bold;\r\n        }\r\n\r\n        /* Right Column Details */\r\n        .cheque-details {\r\n            margin-bottom: 20px;\r\n        }\r\n\r\n        .cheque-number {\r\n            font-size: 11px;\r\n            margin-bottom: 15px;\r\n        }\r\n\r\n        .cash-line {\r\n            margin: 15px 0;\r\n            font-size: 10px;\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 5px;\r\n        }\r\n\r\n        .cash-line input {\r\n            width: 12px;\r\n            height: 12px;\r\n        }\r\n\r\n        .short-line {\r\n            border-bottom: 1px dotted black;\r\n            width: 50px;\r\n            height: 14px;\r\n            display: inline-block;\r\n            margin: 0 3px;\r\n        }\r\n\r\n        .calculations {\r\n            text-align: right;\r\n            margin: 20px 0;\r\n            font-size: 12px;\r\n            font-weight: bold;\r\n        }\r\n\r\n        .calc-row {\r\n            margin-bottom: 6px;\r\n            padding: 2px 0;\r\n        }\r\n\r\n        .total-calc {\r\n            border-top: 1px solid black;\r\n            padding-top: 6px;\r\n            margin-top: 8px;\r\n        }\r\n\r\n        .amount-breakdown {\r\n            margin: 20px 0;\r\n        }\r\n\r\n        .amount-row {\r\n            display: flex;\r\n            justify-content: space-between;\r\n    