     // Function to populate dynamic values\r\n        function populateVoucherData(data) {\r\n            if (data.voucherNumber) {\r\n                document.getElementById(\'voucher-number\').textContent = \'VOUCHER NUMBER: \' + data.voucherNumber;\r\n            }\r\n            if (data.date) {\r\n                document.getElementById(\'voucher-date\').textContent = \'DATE: \' + data.date;\r\n            }\r\n            // Add more dynamic field population as needed\r\n        }\r\n\r\n        // Set current date\r\n        document.addEventListener(\'DOMContentLoaded\', function() {\r\n            const today = new Date();\r\n            const dateString = today.getDate().toString().padStart(2, \'0\') + \'/\' +\r\n                (today.getMonth() + 1).toString().padStart(2, \'0\') + \'/\' +\r\n                today.getFullYear();\r\n\r\n            document.getElementById(\'voucher-date\').textContent = \'DATE: \' + dateString;\r\n        });\r\n    </script>\r\n</body>\r\n\r\n</html>', '2025-09-24 10:36:06', NULL, 8);
INSERT INTO `training_cheque_approvals` (`id`, `training_payment_id`, `voucher_number`, `date`, `account_number`, `name_of_account`, `title_of_project`, `bill_amount`, `vendor_payee_name`, `prp`, `cheque_number`, `cheque_date`, `total_amount`, `date_paid`, `bill_html`, `created_at`, `updated_at`, `training_reimbursement_id`) VALUES
(6, NULL, '674', '2008-06-01', '226', 'Evan Coleman', 'Training Project', 33.00, 'Nill', 'Dicta adipisicing et', '38', '1976-08-23', 33.00, NULL, '\r\n<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <!-- Bootstrap 5 CSS -->\r\n<link href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css\" rel=\"stylesheet\">\r\n    <title>University of Madras Voucher</title>\r\n    <style>\r\n        * {\r\n            margin: 0;\r\n            padding: 0;\r\n            box-sizing: border-box;\r\n        }\r\n\r\n        body {\r\n            font-family: \'Times New Roman\', serif;\r\n            font-size: 12px;\r\n            line-height: 1.4;\r\n            background: #f5f5f0;\r\n            color: black;\r\n            padding: 15px;\r\n        }\r\n\r\n        .voucher-container {\r\n            width: 210mm;\r\n            min-height: 297mm;\r\n            margin: 0 auto;\r\n            background: #f8f8f5;\r\n            border: 2px solid black;\r\n            position: relative;\r\n        }\r\n\r\n        /* Header Section */\r\n        .header {\r\n            display: flex;\r\n            align-items: center;\r\n            padding: 15px 20px;\r\n            border-bottom: 1px solid black;\r\n        }\r\n\r\n        .logo-section {\r\n            width: 70px;\r\n            height: 70px;\r\n            border: 2px solid black;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            margin-right: 20px;\r\n            background: white;\r\n            flex-shrink: 0;\r\n        }\r\n\r\n        .logo-content {\r\n            text-align: center;\r\n            font-size: 8px;\r\n            font-weight: bold;\r\n        }\r\n\r\n        .university-header {\r\n            flex-grow: 1;\r\n            text-align: center;\r\n        }\r\n\r\n        .university-header h1 {\r\n            font-size: 18px;\r\n            font-weight: bold;\r\n            letter-spacing: 2px;\r\n            margin-bottom: 5px;\r\n        }\r\n\r\n        .university-header h2 {\r\n            font-size: 12px;\r\n            font-weight: bold;\r\n            margin-bottom: 3px;\r\n        }\r\n\r\n        .university-header h3 {\r\n            font-size: 14px;\r\n            font-weight: bold;\r\n            letter-spacing: 4px;\r\n        }\r\n\r\n        /* Section and Voucher Info */\r\n        .section-voucher-row {\r\n            display: flex;\r\n            justify-content: space-between;\r\n            padding: 10px 20px;\r\n            border-bottom: 1px solid black;\r\n        }\r\n\r\n        .f-section {\r\n            font-size: 14px;\r\n            font-weight: bold;\r\n        }\r\n\r\n        .voucher-info {\r\n            display: flex;\r\n            flex-direction: column;\r\n            gap: 5px;\r\n        }\r\n\r\n        .voucher-box {\r\n            border: 1px solid black;\r\n            padding: 5px 10px;\r\n            background: white;\r\n            min-height: 30px;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            font-weight: bold;\r\n            font-size: 11px;\r\n            width: 150px;\r\n        }\r\n\r\n        /* Main Form Table */\r\n        .form-table {\r\n            width: 100%;\r\n            border-collapse: collapse;\r\n            margin: 0;\r\n        }\r\n\r\n        .form-table td {\r\n            padding: 8px 15px;\r\n            vertical-align: top;\r\n            border-bottom: 1px solid #ccc;\r\n        }\r\n\r\n        .label-column {\r\n            width: 50%;\r\n            font-weight: bold;\r\n            font-size: 11px;\r\n            background: #f0f0f0;\r\n            border-right: 1px solid black;\r\n        }\r\n\r\n        .value-column {\r\n            width: 50%;\r\n            font-size: 11px;\r\n            background: white;\r\n        }\r\n\r\n        .field-value {\r\n            /* border-bottom: 1px dotted black; */\r\n            min-height: 18px;\r\n            padding: 2px 5px;\r\n            display: block;\r\n            width: 100%;\r\n        }\r\n\r\n        .checkbox-row {\r\n            display: flex;\r\n            gap: 15px;\r\n            flex-wrap: wrap;\r\n            align-items: center;\r\n        }\r\n\r\n        .checkbox-item {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 3px;\r\n        }\r\n\r\n        .checkbox-item input {\r\n            width: 14px;\r\n            height: 14px;\r\n        }\r\n\r\n        .checkbox-item label {\r\n            font-size: 10px;\r\n            font-weight: bold;\r\n        }\r\n\r\n        /* Payment Sections */\r\n        .payment-sections {\r\n            display: flex;\r\n        }\r\n\r\n        .payment-left {\r\n            width: 50%;\r\n            padding: 15px;\r\n            border-right: 1px solid black;\r\n        }\r\n\r\n        .payment-right {\r\n            width: 50%;\r\n            padding: 15px;\r\n        }\r\n\r\n        .payment-box {\r\n            border: 2px solid black;\r\n            margin: 15px 0;\r\n            padding: 15px;\r\n            background: white;\r\n        }\r\n\r\n        .payment-header {\r\n            display: flex;\r\n            align-items: center;\r\n            margin-bottom: 12px;\r\n        }\r\n\r\n        .payment-header input {\r\n            width: 16px;\r\n            height: 16px;\r\n            margin-right: 8px;\r\n        }\r\n\r\n        .payment-header label {\r\n            font-weight: bold;\r\n            font-size: 12px;\r\n        }\r\n\r\n        .rupees-line {\r\n            margin: 12px 0;\r\n            display: flex;\r\n            align-items: center;\r\n        }\r\n\r\n        .rupees-line span {\r\n            font-weight: bold;\r\n            margin-right: 10px;\r\n        }\r\n\r\n        .dots-line {\r\n            flex-grow: 1;\r\n            border-bottom: 1px dotted black;\r\n            height: 16px;\r\n        }\r\n\r\n        .debit-text {\r\n            font-size: 11px;\r\n            margin: 8px 0;\r\n        }\r\n\r\n        .signature-area {\r\n            margin-top: 30px;\r\n            text-align: right;\r\n        }\r\n\r\n        .signature-line {\r\n            width: 150px;\r\n            border-top: 1px solid black;\r\n            margin: 25px 0 5px auto;\r\n        }\r\n\r\n        .signature-text {\r\n            font-size: 11px;\r\n            font-weight: bold;\r\n        }\r\n\r\n        /* Right Column Details */\r\n        .cheque-details {\r\n            margin-bottom: 20px;\r\n        }\r\n\r\n        .cheque-number {\r\n            font-size: 11px;\r\n            margin-bottom: 15px;\r\n        }\r\n\r\n        .cash-line {\r\n            margin: 15px 0;\r\n            font-size: 10px;\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 5px;\r\n        }\r\n\r\n        .cash-line input {\r\n            width: 12px;\r\n            height: 12px;\r\n        }\r\n\r\n        .short-line {\r\n            border-bottom: 1px dotted black;\r\n            width: 50px;\r\n            height: 14px;\r\n            display: inline-block;\r\n            margin: 0 3px;\r\n        }\r\n\r\n        .calculations {\r\n            text-align: right;\r\n            margin: 20px 0;\r\n            font-size: 12px;\r\n            font-weight: bold;\r\n        }\r\n\r\n        .calc-row {\r\n            margin-bottom: 6px;\r\n            padding: 2px 0;\r\n        }\r\n\r\n        .total-calc {\r\n            border-top: 1px solid black;\r\n            padding-top: 6px;\r\n            margin-top: 8px;\r\n        }\r\n\r\n        .amount-breakdown {\r\n            margin: 20px 0;\r\n        }\r\n\r\n        .amount-row {\r\n            display: flex;\r\n            justify-content: space-between;\r\n            align-items: center;\r\n            margin-bottom: 30px;\r\n            font-size: 10px;\r\n        }\r\n\r\n        .amount-number {\r\n            width: 20px;\r\n            font-weight: bold;\r\n        }\r\n\r\n        .amount-desc {\r\n            flex-grow: 1;\r\n            margin: 0 8px;\r\n        }\r\n\r\n        .amount-dots {\r\n            flex-grow: 1;\r\n            border-bottom: 1px dotted black;\r\n            height: 14px;\r\n            font-weight: bold;\r\n            font-size: 10px;\r\n        }\r\n\r\n        .amount-value {\r\n            width: 50px;\r\n            text-align: right;\r\n            font-weight: bold;\r\n        }\r\n\r\n        .cheque-summary {\r\n            text-align: start;\r\n            margin: 25px 0;\r\n            font-size: 10px;\r\n        }\r\n\r\n        .cheque-summary-line {\r\n            margin: 6px 0;\r\n        }\r\n\r\n        .final-total-section {\r\n            /* border-top: 2px solid black; */\r\n            padding-top: 15px;\r\n            margin-top: 25px;\r\n            text-align: start;\r\n        }\r\n\r\n        .total-line-final {\r\n            display: flex;\r\n            align-items: start;\r\n            justify-content: start;\r\n            margin: 12px 0;\r\n        }\r\n\r\n        .total-line-final span {\r\n            font-weight: bold;\r\n            margin-right: 10px;\r\n        }\r\n\r\n        .long-line {\r\n            border-bottom: 1px dotted black;\r\n            width: 120px;\r\n            height: 16px;\r\n            display: inline-block;\r\n        }\r\n\r\n        .registrar-section {\r\n            margin-top: 30px;\r\n            text-align: end;\r\n        }\r\n\r\n        .registrar-title {\r\n            font-weight: bold;\r\n            font-size: 13px;\r\n            margin-bottom: 20px;\r\n        }\r\n\r\n        .final-checkboxes {\r\n            display: flex;\r\n            justify-content: end;\r\n            gap: 20px;\r\n        }\r\n\r\n        /* Print Styles */\r\n        @media print {\r\n            body {\r\n                padding: 0;\r\n                background: white;\r\n            }\r\n\r\n            .voucher-container {\r\n                width: 100%;\r\n                min-height: auto;\r\n                background: white;\r\n            }\r\n\r\n            .no-print {\r\n                display: none;\r\n            }\r\n        }\r\n    </style>\r\n</head>\r\n\r\n<body>\r\n    <div class=\"voucher-container\">\r\n        <!-- Header -->\r\n        <div class=\"header\">\r\n            <div class=\"logo-section\">\r\n                <div class=\"logo-content\">\r\n                    UNIVERSITY<br>\r\n                    LOGO\r\n                </div>\r\n            </div>\r\n            <div class=\"university-header\">\r\n                <h1>UNIVERSITY OF MADRAS</h1>\r\n                <h2>GUINDY CAMPUS UICIC OFFICE</h2>\r\n\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Section and Voucher Info -->\r\n        <div class=\"section-voucher-row\">\r\n            \r\n            <div class=\"labels\" style=\"display: flex; flex-direction: column; justify-content: space-around;\">\r\n                    <label for=\"\" class=\"form-control\">Voucher Number</label>\r\n                    <label for=\"\" class=\"form-control\">Voucher Date</label>\r\n                </div>\r\n            <div class=\"voucher-info\" style=\"display: flex; align-items: flex-start; justify-content: space-between;\">\r\n                \r\n                <div class=\"vochervalues\">\r\n                    <div class=\"f-section\">F-Section</div>\r\n                    <div class=\"voucher-box\" id=\"voucher-number\">674</div>\r\n                    <div class=\"voucher-box\" id=\"voucher-date\">2008-06-01</div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Form Table -->\r\n        <table class=\"form-table\">\r\n            <tr>\r\n                <td class=\"label-column\">Account Number :</td>\r\n                <td class=\"value-column\">\r\n                    <span class=\"field-value\">226</span>\r\n                </td>\r\n            </tr>\r\n            <tr>\r\n                <td class=\"label-column\">NAME OF ACCOUNT</td>\r\n                <td class=\"value-column\">\r\n                    <span class=\"field-value\">Registrar, University of Madras</span>\r\n\r\n                    <span class=\"field-value\">Dean, Industrial Consultancy</span>\r\n                </td>\r\n            </tr>\r\n            <tr>\r\n                <td class=\"label-column\">CLASSIFICATION</td>\r\n                <td class=\"value-column\">\r\n                    <span class=\"field-value\">Training Project</span>\r\n                    <span class=\"field-value\">Kalia Ortega</span>\r\n                    <span class=\"field-value\">Rerum dolores volupt</span>\r\n                </td>\r\n            </tr>\r\n            <tr>\r\n                <td class=\"label-column\">DATE OF SANCTION BY<br>V.C. / REGISTRAR / DIRECTOR/ F.O.</td>\r\n                <td class=\"value-column\">\r\n                    <div class=\"checkbox-row\">\r\n                        <div class=\"checkbox-item\">\r\n                            <input type=\"checkbox\">\r\n                            <label>V.C.</label>\r\n                        </div>\r\n                        <div class=\"checkbox-item\">\r\n                            <input type=\"checkbox\">\r\n                            <label>REGISTRAR</label>\r\n                        </div>\r\n                        <div class=\"checkbox-item\">\r\n                            <input type=\"checkbox\">\r\n                            <label>DIRECTOR</label>\r\n                        </div>\r\n                        <div class=\"checkbox-item\">\r\n                            <input type=\"checkbox\">\r\n                            <label>F.O.</label>\r\n                        </div>\r\n                    </div>\r\n                </td>\r\n            </tr>\r\n            <tr>\r\n                <td class=\"label-column\">SECTION ADVISING PAYMENT<br>AND FILE NUMBER</td>\r\n                <td class=\"value-column\">\r\n                    <span class=\"field-value\"></span>\r\n                </td>\r\n            </tr>\r\n            <tr>\r\n                <td class=\"label-column\">AMOUNT</td>\r\n                <td class=\"value-column\">\r\n                    <span class=\"field-value\">(Rs.) 33.00</span>\r\n                </td>\r\n            </tr>\r\n            <tr>\r\n                <td class=\"label-column\">NAME OF PAYEE</td>\r\n                <td class=\"value-column\">\r\n                    <span class=\"field-value\">Nill</span>\r\n                </td>\r\n            </tr>\r\n        </table>\r\n\r\n        <!-- Payment Sections -->\r\n        <div class=\"payment-sections\">\r\n            <!-- Left Payment Column -->\r\n            <div class=\"payment-left\">\r\n\r\n                <table class=\"table table-bordered\">\r\n                    <thead>\r\n                        <th>SRP/ARP</th>\r\n                        <th> </th>\r\n                    </thead>\r\n                    <tbody>\r\n                        <td>PRP</td>\r\n                        <td>Dicta adipisicing et</td>\r\n                    </tbody>\r\n\r\n                </table>\r\n\r\n                <!-- Payment Box 1 -->\r\n                <div class=\"payment-box\">\r\n                    <div class=\"payment-header\">\r\n                        <!-- <input type=\"checkbox\"> -->\r\n                        <label>Passed by Adjustment</label>\r\n                    </div>\r\n                    <div class=\"rupees-line\">\r\n                        <span>Rupees</span>\r\n                        <div class=\"dots-line\"></div>\r\n                    </div>\r\n                    <div class=\"debit-text\">debited to Non-Plan account</div>\r\n                    <div class=\"debit-text\">University of Madras</div>\r\n                    <div class=\"signature-area\">\r\n                        <div class=\"signature-line\"></div>\r\n                        <div class=\"signature-text\">Registrar</div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Payment Box 2 -->\r\n                <div class=\"payment-box\">\r\n                    <div class=\"payment-header\">\r\n                        <!-- <input type=\"checkbox\" checked> -->\r\n                        <label>Paid by Cheque</label>\r\n                    </div>\r\n                    <div class=\"rupees-line\">\r\n                        <span>Rupees</span>\r\n                        <div class=\"dots-line\"></div>\r\n                    </div>\r\n                    <div class=\"debit-text\">and debited to Account, University of Madras</div>\r\n                    <div class=\"signature-area\">\r\n                        <div class=\"signature-line\"></div>\r\n                        <div class=\"signature-text\">Registrar</div>\r\n                    </div>\r\n                </div>\r\n                <div class=\"payment-box\">\r\n                    <div class=\"payment-header\">\r\n                        <!-- <input type=\"checkbox\" > -->\r\n                        <label>Paid by Cheque</label>\r\n                    </div>\r\n                    <div class=\"rupees-line\">\r\n                        <span>by Cheque No.(s) </span>\r\n                        <div class=\"dots-line\">38 / 1976-08-23</div>\r\n                    </div>\r\n                    <div class=\"rupees-line\">\r\n                        <span>Paid </span>\r\n                        <div class=\"dots-line\"></div>\r\n                    </div>\r\n                    <div class=\"debit-text\">In Cash</div>\r\n                    <div class=\"rupees-line\">\r\n                        <span>Rs </span>\r\n                        <div class=\"dots-line\"></div>\r\n                    </div>\r\n                    <div class=\"rupees-line\">\r\n                        <span>Date </span>\r\n                        <div class=\"dots-line\"></div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Right Payment Column -->\r\n            <div class=\"payment-right\">\r\n\r\n\r\n\r\n\r\n                <div class=\"amount-breakdown\">\r\n                    <div class=\"amount-row\">\r\n                        <span class=\"amount-number\">1.</span>\r\n                        <span class=\"amount-dots\">Nill</span>\r\n                        <span class=\"amount-value\"></span>\r\n                    </div>\r\n                    <div class=\"amount-row\">\r\n                        <span class=\"amount-number\">2.</span>\r\n                        <span class=\"amount-dots\">Nill</span>\r\n                        <span class=\"amount-value\"> </span>\r\n                    </div>\r\n                    <div class=\"amount-row\">\r\n                        <span class=\"amount-number\">3.</span>\r\n                        <span class=\"amount-dots\"></span>\r\n                        <span class=\"amount-value\"></span>\r\n                    </div>\r\n                    <div class=\"amount-row\">\r\n                        <span class=\"amount-number\">4.</span>\r\n                        <span class=\"amount-dots\"></span>\r\n                        <span class=\"amount-value\"></span>\r\n                    </div>\r\n                    <div class=\"amount-row\">\r\n                        <span class=\"amount-number\">5.</span>\r\n                        <span class=\"amount-dots\"></span>\r\n                        <span class=\"amount-value\"></span>\r\n                    </div>\r\n\r\n                    <div class=\"calculations\">\r\n                        <div class=\"calc-row\">Nill /-</div>\r\n                        <div class=\"calc-row\">Nill /-</div>\r\n                        <div class=\"calc-row total-calc\">33.00 /-</div>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cheque-summary\">\r\n                    <div class=\"cheque-summary-line\">Cheque(s) for Rs. <span class=\"short-line fw-bold\">33.00</span> drawn as detailed</div>\r\n                    <div class=\"cheque-summary-line\">above and sent</div>\r\n                </div>\r\n\r\n                <div class=\"final-total-section\">\r\n                    <div class=\"total-line-final\">\r\n                        <span>Total Rs.</span>\r\n                        <span class=\"long-line\">33.00</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"registrar-section\">\r\n                    <div class=\"registrar-title\">REGISTRAR</div>\r\n                    <div class=\"final-checkboxes\">\r\n                        <div class=\"checkbox-item\">\r\n                            <input type=\"checkbox\">\r\n                            <label>F.O.</label>\r\n                        </div>\r\n                        <div class=\"checkbox-item\">\r\n                            <input type=\"checkbox\">\r\n                            <label>A.R.</label>\r\n                        </div>\r\n                        <div class=\"checkbox-item\">\r\n                            <input type=\"checkbox\">\r\n                            <label>S.O.</label>\r\n                        </div>\r\n                        <div class=\"checkbox-item\">\r\n                            <input type=\"checkbox\">\r\n                            <label>A.S.O.</label>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <!-- Print Button -->\r\n   <script>\r\n        window.onload = function() {\r\n            window.print();\r\n        }\r\n    </script>\r\n\r\n    <script>\r\n        // Function to populate dynamic values\r\n        function populateVoucherData(data) {\r\n            if (data.voucherNumber) {\r\n                document.getElementById(\'voucher-number\').textContent = \'VOUCHER NUMBER: \' + data.voucherNumber;\r\n            }\r\n            if (data.date) {\r\n                document.getElementById(\'voucher-date\').textContent = \'DATE: \' + data.date;\r\n            }\r\n            // Add more dynamic field population as needed\r\n        }\r\n\r\n        // Set current date\r\n        document.addEventListener(\'DOMContentLoaded\', function() {\r\n            const today = new Date();\r\n            const dateString = today.getDate().toString().padStart(2, \'0\') + \'/\' +\r\n                (today.getMonth() + 1).toString().padStart(2, \'0\') + \'/\' +\r\n                today.getFullYear();\r\n\r\n            document.getElementById(\'voucher-date\').textContent = \'DATE: \' + dateString;\r\n        });\r\n    </script>\r\n</body>\r\n\r\n</html>', '2025-09-24 10:42:11', NULL, 8),
(7, NULL, '729', '1996-05-04', '917', 'Ariana Rosa', 'Training Project', 33.00, 'Nill', 'Dicta adipisicing et', '477', '1996-12-29', 33.00, NULL, '\r\n<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <!-- Bootstrap 5 CSS -->\r\n<link href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css\" rel=\"stylesheet\">\r\n    <title>University of Madras Voucher</title>\r\n    <style>\r\n        * {\r\n            margin: 0;\r\n            padding: 0;\r\n            box-sizing: border-box;\r\n        }\r\n\r\n        body {\r\n            font-family: \'Times New Roman\', serif;\r\n            font-size: 12px;\r\n            line-height: 1.4;\r\n            background: #f5f5f0;\r\n            color: black;\r\n            padding: 15px;\r\n        }\r\n\r\n        .voucher-container {\r\n            width: 210mm;\r\n            min-height: 297mm;\r\n            margin: 0 auto;\r\n            background: #f8f8f5;\r\n            border: 2px solid black;\r\n            position: relative;\r\n        }\r\n\r\n        /* Header Section */\r\n        .header {\r\n            display: flex;\r\n            align-items: center;\r\n            padding: 15px 20px;\r\n            border-bottom: 1px solid black;\r\n        }\r\n\r\n        .logo-section {\r\n            width: 70px;\r\n            height: 70px;\r\n            border: 2px solid black;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            margin-right: 20px;\r\n            background: white;\r\n            flex-shrink: 0;\r\n        }\r\n\r\n        .logo-content {\r\n            text-align: center;\r\n            font-size: 8px;\r\n            font-weight: bold;\r\n        }\r\n\r\n        .university-header {\r\n            flex-grow: 1;\r\n            text-align: center;\r\n        }\r\n\r\n        .university-h