      background: white;\r\n        }\r\n\r\n        .field-value {\r\n            /* border-bottom: 1px dotted black; */\r\n            min-height: 18px;\r\n            padding: 2px 5px;\r\n            display: block;\r\n            width: 100%;\r\n        }\r\n\r\n        .checkbox-row {\r\n            display: flex;\r\n            gap: 15px;\r\n            flex-wrap: wrap;\r\n            align-items: center;\r\n        }\r\n\r\n        .checkbox-item {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 3px;\r\n        }\r\n\r\n        .checkbox-item input {\r\n            width: 14px;\r\n            height: 14px;\r\n        }\r\n\r\n        .checkbox-item label {\r\n            font-size: 10px;\r\n            font-weight: bold;\r\n        }\r\n\r\n        /* Payment Sections */\r\n        .payment-sections {\r\n            display: flex;\r\n        }\r\n\r\n        .payment-left {\r\n            width: 50%;\r\n            padding: 15px;\r\n            border-right: 1px solid black;\r\n        }\r\n\r\n        .payment-right {\r\n            width: 50%;\r\n            padding: 15px;\r\n        }\r\n\r\n        .payment-box {\r\n            border: 2px solid black;\r\n            margin: 15px 0;\r\n            padding: 15px;\r\n            background: white;\r\n        }\r\n\r\n        .payment-header {\r\n            display: flex;\r\n            align-items: center;\r\n            margin-bottom: 12px;\r\n        }\r\n\r\n        .payment-header input {\r\n            width: 16px;\r\n            height: 16px;\r\n            margin-right: 8px;\r\n        }\r\n\r\n        .payment-header label {\r\n            font-weight: bold;\r\n            font-size: 12px;\r\n        }\r\n\r\n        .rupees-line {\r\n            margin: 12px 0;\r\n            display: flex;\r\n            align-items: center;\r\n        }\r\n\r\n        .rupees-line span {\r\n            font-weight: bold;\r\n            margin-right: 10px;\r\n        }\r\n\r\n        .dots-line {\r\n            flex-grow: 1;\r\n            border-bottom: 1px dotted black;\r\n            height: 16px;\r\n        }\r\n\r\n        .debit-text {\r\n            font-size: 11px;\r\n            margin: 8px 0;\r\n        }\r\n\r\n        .signature-area {\r\n            margin-top: 30px;\r\n            text-align: right;\r\n        }\r\n\r\n        .signature-line {\r\n            width: 150px;\r\n            border-top: 1px solid black;\r\n            margin: 25px 0 5px auto;\r\n        }\r\n\r\n        .signature-text {\r\n            font-size: 11px;\r\n            font-weight: bold;\r\n        }\r\n\r\n        /* Right Column Details */\r\n        .cheque-details {\r\n            margin-bottom: 20px;\r\n        }\r\n\r\n        .cheque-number {\r\n            font-size: 11px;\r\n            margin-bottom: 15px;\r\n        }\r\n\r\n        .cash-line {\r\n            margin: 15px 0;\r\n            font-size: 10px;\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 5px;\r\n        }\r\n\r\n        .cash-line input {\r\n            width: 12px;\r\n            height: 12px;\r\n        }\r\n\r\n        .short-line {\r\n            border-bottom: 1px dotted black;\r\n            width: 50px;\r\n            height: 14px;\r\n            display: inline-block;\r\n            margin: 0 3px;\r\n        }\r\n\r\n        .calculations {\r\n            text-align: right;\r\n            margin: 20px 0;\r\n            font-size: 12px;\r\n            font-weight: bold;\r\n        }\r\n\r\n        .calc-row {\r\n            margin-bottom: 6px;\r\n            padding: 2px 0;\r\n        }\r\n\r\n        .total-calc {\r\n            border-top: 1px solid black;\r\n            padding-top: 6px;\r\n            margin-top: 8px;\r\n        }\r\n\r\n        .amount-breakdown {\r\n            margin: 20px 0;\r\n        }\r\n\r\n        .amount-row {\r\n            display: flex;\r\n            justify-content: space-between;\r\n            align-items: center;\r\n            margin-bottom: 30px;\r\n            font-size: 10px;\r\n        }\r\n\r\n        .amount-number {\r\n            width: 20px;\r\n            font-weight: bold;\r\n        }\r\n\r\n        .amount-desc {\r\n            flex-grow: 1;\r\n            margin: 0 8px;\r\n        }\r\n\r\n        .amount-dots {\r\n            flex-grow: 1;\r\n            border-bottom: 1px dotted black;\r\n            height: 14px;\r\n            font-weight: bold;\r\n            font-size: 10px;\r\n        }\r\n\r\n        .amount-value {\r\n            width: 50px;\r\n            text-align: right;\r\n            font-weight: bold;\r\n        }\r\n\r\n        .cheque-summary {\r\n            text-align: start;\r\n            margin: 25px 0;\r\n            font-size: 10px;\r\n        }\r\n\r\n        .cheque-summary-line {\r\n            margin: 6px 0;\r\n        }\r\n\r\n        .final-total-section {\r\n            /* border-top: 2px solid black; */\r\n            padding-top: 15px;\r\n            margin-top: 25px;\r\n            text-align: start;\r\n        }\r\n\r\n        .total-line-final {\r\n            display: flex;\r\n            align-items: start;\r\n            justify-content: start;\r\n            margin: 12px 0;\r\n        }\r\n\r\n        .total-line-final span {\r\n            font-weight: bold;\r\n            margin-right: 10px;\r\n        }\r\n\r\n        .long-line {\r\n            border-bottom: 1px dotted black;\r\n            width: 120px;\r\n            height: 16px;\r\n            display: inline-block;\r\n        }\r\n\r\n        .registrar-section {\r\n            margin-top: 30px;\r\n            text-align: end;\r\n        }\r\n\r\n        .registrar-title {\r\n            font-weight: bold;\r\n            font-size: 13px;\r\n            margin-bottom: 20px;\r\n        }\r\n\r\n        .final-checkboxes {\r\n            display: flex;\r\n            justify-content: end;\r\n            gap: 20px;\r\n        }\r\n\r\n        /* Print Styles */\r\n        @media print {\r\n            body {\r\n                padding: 0;\r\n                background: white;\r\n            }\r\n\r\n            .voucher-container {\r\n                width: 100%;\r\n                min-height: auto;\r\n                background: white;\r\n            }\r\n\r\n            .no-print {\r\n                display: none;\r\n            }\r\n        }\r\n    </style>\r\n</head>\r\n\r\n<body>\r\n    <div class=\"voucher-container\">\r\n        <!-- Header -->\r\n        <div class=\"header\">\r\n            <div class=\"logo-section\">\r\n                <div class=\"logo-content\">\r\n                    UNIVERSITY<br>\r\n                    LOGO\r\n                </div>\r\n            </div>\r\n            <div class=\"university-header\">\r\n                <h1>UNIVERSITY OF MADRAS</h1>\r\n                <h2>GUINDY CAMPUS UICIC OFFICE</h2>\r\n\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Section and Voucher Info -->\r\n        <div class=\"section-voucher-row\">\r\n            \r\n            <div class=\"labels\" style=\"display: flex; flex-direction: column; justify-content: space-around;\">\r\n                    <label for=\"\" class=\"form-control\">Voucher Number</label>\r\n                    <label for=\"\" class=\"form-control\">Voucher Date</label>\r\n                </div>\r\n            <div class=\"voucher-info\" style=\"display: flex; align-items: flex-start; justify-content: space-between;\">\r\n                \r\n                <div class=\"vochervalues\">\r\n                    <div class=\"f-section\">F-Section</div>\r\n                    <div class=\"voucher-box\" id=\"voucher-number\">729</div>\r\n                    <div class=\"voucher-box\" id=\"voucher-date\">1996-05-04</div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Form Table -->\r\n        <table class=\"form-table\">\r\n            <tr>\r\n                <td class=\"label-column\">Account Number :</td>\r\n                <td class=\"value-column\">\r\n                    <span class=\"field-value\">917</span>\r\n                </td>\r\n            </tr>\r\n            <tr>\r\n                <td class=\"label-column\">NAME OF ACCOUNT</td>\r\n                <td class=\"value-column\">\r\n                    <span class=\"field-value\">Registrar, University of Madras</span>\r\n\r\n                    <span class=\"field-value\">Dean, Industrial Consultancy</span>\r\n                </td>\r\n            </tr>\r\n            <tr>\r\n                <td class=\"label-column\">CLASSIFICATION</td>\r\n                <td class=\"value-column\">\r\n                    <span class=\"field-value\">Training Project</span>\r\n                    <span class=\"field-value\">Kalia Ortega</span>\r\n                    <span class=\"field-value\">Rerum dolores volupt</span>\r\n                </td>\r\n            </tr>\r\n            <tr>\r\n                <td class=\"label-column\">DATE OF SANCTION BY<br>V.C. / REGISTRAR / DIRECTOR/ F.O.</td>\r\n                <td class=\"value-column\">\r\n                    <div class=\"checkbox-row\">\r\n                        <div class=\"checkbox-item\">\r\n                            <input type=\"checkbox\">\r\n                            <label>V.C.</label>\r\n                        </div>\r\n                        <div class=\"checkbox-item\">\r\n                            <input type=\"checkbox\">\r\n                            <label>REGISTRAR</label>\r\n                        </div>\r\n                        <div class=\"checkbox-item\">\r\n                            <input type=\"checkbox\">\r\n                            <label>DIRECTOR</label>\r\n                        </div>\r\n                        <div class=\"checkbox-item\">\r\n                            <input type=\"checkbox\">\r\n                            <label>F.O.</label>\r\n                        </div>\r\n                    </div>\r\n                </td>\r\n            </tr>\r\n            <tr>\r\n                <td class=\"label-column\">SECTION ADVISING PAYMENT<br>AND FILE NUMBER</td>\r\n                <td class=\"value-column\">\r\n                    <span class=\"field-value\"></span>\r\n                </td>\r\n            </tr>\r\n            <tr>\r\n                <td class=\"label-column\">AMOUNT</td>\r\n                <td class=\"value-column\">\r\n                    <span class=\"field-value\">(Rs.) 33.00</span>\r\n                </td>\r\n            </tr>\r\n            <tr>\r\n                <td class=\"label-column\">NAME OF PAYEE</td>\r\n                <td class=\"value-column\">\r\n                    <span class=\"field-value\">Nill</span>\r\n                </td>\r\n            </tr>\r\n        </table>\r\n\r\n        <!-- Payment Sections -->\r\n        <div class=\"payment-sections\">\r\n            <!-- Left Payment Column -->\r\n            <div class=\"payment-left\">\r\n\r\n                <table class=\"table table-bordered\">\r\n                    <thead>\r\n                        <th>SRP/ARP</th>\r\n                        <th> </th>\r\n                    </thead>\r\n                    <tbody>\r\n                        <td>PRP</td>\r\n                        <td>Dicta adipisicing et</td>\r\n                    </tbody>\r\n\r\n                </table>\r\n\r\n                <!-- Payment Box 1 -->\r\n                <div class=\"payment-box\">\r\n                    <div class=\"payment-header\">\r\n                        <!-- <input type=\"checkbox\"> -->\r\n                        <label>Passed by Adjustment</label>\r\n                    </div>\r\n                    <div class=\"rupees-line\">\r\n                        <span>Rupees</span>\r\n                        <div class=\"dots-line\"></div>\r\n                    </div>\r\n                    <div class=\"debit-text\">debited to Non-Plan account</div>\r\n         